package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Date;
import java.util.TimeZone;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StdDateFormat._parseDate
 */
public class StdDateFormat__parseDate_TriageGen2Test {

    private StdDateFormat _format;

    @Before
    public void setUp() {
        _format = new StdDateFormat();
    }

    /**
     * A subclass to expose the protected method for testing
     */
    private static class TestableStdDateFormat extends StdDateFormat {
        public Date testParseDate(String dateStr, ParsePosition pos) throws ParseException {
            return super._parseDate(dateStr, pos);
        }
    }

    private TestableStdDateFormat _testableFormat;

    @Before
    public void setUpTestable() {
        _testableFormat = new TestableStdDateFormat();
    }

    @Test
    public void testParseDate_ISO8601() throws ParseException {
        // Tests the first branch: looksLikeISO8601(dateStr)
        String isoDate = "2023-10-27T10:00:00Z";
        Date result = _testableFormat.testParseDate(isoDate, new ParsePosition(0));
        assertNotNull(result);

        // Test with offset
        String isoDateWithOffset = "2023-10-27T10:00:00+02:00";
        Date result2 = _testableFormat.testParseDate(isoDateWithOffset, new ParsePosition(0));
        assertNotNull(result2);
    }

    @Test
    public void testParseDate_LongTimestamp_Positive() throws ParseException {
        // Tests the branch: (i < 0) && (dateStr.charAt(0) == '-' || NumberInput.inLongRange(dateStr, false))
        // Using a valid epoch millisecond string
        String longDate = "1698393600000"; 
        Date result = _testableFormat.testParseDate(longDate, new ParsePosition(0));
        assertNotNull(result);
    }

    @Test
    public void testParseDate_LongTimestamp_Negative() throws ParseException {
        // Tests the branch: dateStr.charAt(0) == '-'
        String negativeLongDate = "-1698393600000";
        Date result = _testableFormat.testParseDate(negativeLongDate, new ParsePosition(0));
        assertNotNull(result);
    }

    @Test
    public void testParseDate_RFC1123() throws ParseException {
        // Tests the fallback branch: parseAsRFC1123
        String rfcDate = "Fri, 27 Oct 2023 10:00:00 GMT";
        Date result = _testableFormat.testParseDate(rfcDate, new ParsePosition(0));
        assertNotNull(result);
    }

    @Test
    public void testParseDate_RFC1123_InvalidReturnsNull() throws ParseException {
        // parseAsRFC1123 is noted to NOT throw, but return null if it fails
        String invalidDate = "Not a date at all";
        Date result = _testableFormat.testParseDate(invalidDate, new ParsePosition(0));
        assertNull(result);
    }

    @Test
    public void testParseDate_MixedContent_TriggersRFC1123() throws ParseException {
        // Tests the loop logic where a non-digit/non-minus char is found
        // "07-Aug-2013" -> loop hits 'A', breaks, i is not < 0, falls to RFC1123
        String mixedDate = "07-Aug-2013";
        Date result = _testableFormat.testParseDate(mixedDate, new ParsePosition(0));
        // RFC1123 might not parse this specific format depending on locale, 
        // but it tests the logic path of the loop and the fallback.
        // In StdDateFormat, this specific string usually fails RFC1123 and returns null.
        assertNull(result);
    }

    @Test
    public void testParseDate_SingleMinusSign_TriggersRFC1123() throws ParseException {
        // Tests the specific logic: if (i > 0 || ch != '-') { break; }
        // If the string is just "-", i will be 0, ch is '-', loop breaks or continues?
        // If dateStr is "-", i starts at 1. i-- makes i=0. ch = '-'. 
        // The condition (i > 0 || ch != '-') is false. Loop continues.
        // Next i is -1. Loop terminates. i < 0 is true.
        // But charAt(0) is '-', so it tries _parseDateFromLong.
        // This tests the 'negative numbers should also work' comment logic.
        String singleMinus = "-";
        // This might throw exception inside _parseDateFromLong or return null via RFC1123
        try {
            _testableFormat.testParseDate(singleMinus, new ParsePosition(0));
        } catch (Exception e) {
            // Expected if _parseDateFromLong fails on a single "-"
        }
    }
}
